To prevent runtime property access errors and ensure robust data processing, we should explicitly validate each entry in `plainTextItems` before processing. If any entry is null, not an object, or missing required fields, we should record it as a malformed entry diagnostic, skip it, and pass those diagnostics to the validator to fail closed. This aligns with the repository's general rules on validating collections of data.

```javascript
function buildRows({ plainTextItems, consumptionItems, sourceRegistryRows, cropRiskRows, paths, generatedAt, diagnostics = [] }) {
  const consumptionByStorage = indexedItems(consumptionItems);
  const registryBySourcePdf = registryIndex(sourceRegistryRows);
  const cropBySourceAndQuestion = cropRiskIndex(cropRiskRows);

  const validItemsWithIndex = [];
  plainTextItems.forEach((item, rowIndex) => {
    if (!item || typeof item !== 'object') {
      diagnostics.push({
        type: 'malformed_entry',
        index: rowIndex,
        reason: 'Entry is not a valid object',
      });
      return;
    }
    const missingFields = ['storage_key', 'subject_code', 'year', 'session', 'paper', 'variant', 'q_number', 'source_pdf'].filter(
      (field) => !(field in item)
    );
    if (missingFields.length > 0) {
      diagnostics.push({
        type: 'malformed_entry',
        index: rowIndex,
        reason: `Missing required fields: ${missingFields.join(', ')}`,
        storage_key: item.storage_key,
      });
      return;
    }
    validItemsWithIndex.push({ item, originalIndex: rowIndex });
  });

  return validItemsWithIndex.map(({ item, originalIndex }) => {
    const normalizedTextPresent = typeof item.normalized_plain_text === 'string' && item.normalized_plain_text.trim().length > 0;
    const rowForPosture = {
      ...item,
      normalized_text_present: normalizedTextPresent,
    };
    const paperCode = paperCodeFromRow(item);
    const questionNumber = zeroPadQuestion(item.q_number);
    const consumptionMatch = consumptionByStorage.get(item.storage_key) ?? null;
    const registryMatch = registryBySourcePdf.get(item.source_pdf) ?? null;
    const cropMatch = cropBySourceAndQuestion.get(sourceDocumentKey(item.source_pdf, item.q_number)) ?? null;

    return {
      question_key: questionKeyFrom(item),
      question_row_id: questionKeyFrom(item),
      storage_key: item.storage_key,
      subject_code: item.subject_code,
      paper_code: paperCode,
      question_ref: `${paperCode}:q${questionNumber}`,
      year: item.year,
      session: item.session,
      paper_number: item.paper,
      variant: item.variant,
      q_number: item.q_number,
      source_pdf: item.source_pdf,
      primary_topic_path: item.primary_topic_path,
      normalized_text_present: normalizedTextPresent,
      normalized_plain_text_status: normalizedTextPresent ? 'present' : 'missing',
      text_only_addressable: item.text_only_addressable === true,
      requires_image_context: item.requires_image_context === true,
      has_diagram: item.has_diagram === true,
      table_heavy: item.table_heavy === true,
      source_visual_requirement: sourceVisualRequirement(item),
      question_availability: questionAvailability(rowForPosture),
      display_posture: displayPosture(item),
      figure_asset_posture: figureAssetPosture(item),
      rights_display_status: 'rights_review_required_no_student_display_claim',
      evidence_availability_status: 'unavailable',
      method_diagnostic_posture: 'routing_logging_review_queue_only',
      method_confidence_blocks_availability: false,
      student_display_eligible_final: false,
      source_refs: sourceRefsFor({
        row: item,
        rowIndex: originalIndex,
        consumptionMatch,
        registryMatch,
        cropMatch,
        paths,
      }),
      blockers: displayBlockers(rowForPosture),
      lineage: {
        generated_by: 'build-full-beta-runtime-source-map.mjs',
        generated_at: generatedAt,
      },
    };
  }).sort(compareSourceMapRows);
}
